using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using Microsoft.Win32;using System.Windows.Forms;
internal sealed class WeixinLocation {public string Dll,Launcher;}
internal static class WeixinLocator {
 static readonly object Gate=new object();static WeixinLocation cached;static DateTime checkedAt;static string storeKey;
 static string Setting{get{return Path.Combine(Engine.Store,"weixin-location.txt");}}
 public static void Reset(){lock(Gate){cached=null;checkedAt=DateTime.MinValue;}}
 public static WeixinLocation Current(){lock(Gate){if(storeKey==Engine.Store&&cached!=null&&File.Exists(cached.Dll)&&DateTime.UtcNow-checkedAt<TimeSpan.FromSeconds(30))return cached;var seeds=new List<string>();foreach(var p in Process.GetProcessesByName("Weixin")){using(p){try{foreach(ProcessModule m in p.Modules)if(String.Equals(m.ModuleName,"Weixin.dll",StringComparison.OrdinalIgnoreCase))seeds.Add(m.FileName);}catch{}try{seeds.Add(p.MainModule.FileName);}catch{}}}try{seeds.Add(File.ReadAllText(Setting).Trim());}catch{}foreach(var hive in new[]{RegistryHive.CurrentUser,RegistryHive.LocalMachine})foreach(var view in new[]{RegistryView.Registry64,RegistryView.Registry32})try{using(var root=RegistryKey.OpenBaseKey(hive,view)){foreach(var name in new[]{@"SOFTWARE\Tencent\Weixin",@"SOFTWARE\Tencent\WeChat",@"SOFTWARE\Microsoft\Windows\CurrentVersion\App Paths\Weixin.exe"})using(var k=root.OpenSubKey(name))if(k!=null)foreach(string field in new[]{"InstallPath","InstallLocation","Path",""}){var v=k.GetValue(field) as string;if(!String.IsNullOrWhiteSpace(v))seeds.Add(v);}using(var u=root.OpenSubKey(@"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall"))if(u!=null)foreach(string name in u.GetSubKeyNames())using(var k=u.OpenSubKey(name)){string display=k.GetValue("DisplayName","").ToString();if(display.IndexOf("微信",StringComparison.OrdinalIgnoreCase)<0&&display.IndexOf("Weixin",StringComparison.OrdinalIgnoreCase)<0&&display.IndexOf("WeChat",StringComparison.OrdinalIgnoreCase)<0)continue;foreach(string field in new[]{"InstallLocation","DisplayIcon"}){var v=k.GetValue(field) as string;if(!String.IsNullOrWhiteSpace(v))seeds.Add(v);}}}}catch{}
 foreach(string folder in new[]{Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86),Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData)})if(!String.IsNullOrEmpty(folder))foreach(string suffix in new[]{@"Tencent\Weixin",@"Tencent\WeChat",@"Programs\Weixin"})seeds.Add(Path.Combine(folder,suffix));foreach(var drive in DriveInfo.GetDrives())try{if(drive.DriveType==DriveType.Fixed&&drive.IsReady)foreach(string suffix in new[]{"Weixin",@"Tencent\Weixin",@"Program Files\Tencent\Weixin",@"Program Files (x86)\Tencent\Weixin",@"Software\Weixin",@"软件\Weixin"})seeds.Add(Path.Combine(drive.RootDirectory.FullName,suffix));}catch{}
 cached=Find(seeds);checkedAt=DateTime.UtcNow;storeKey=Engine.Store;if(cached==null)throw new FileNotFoundException("未找到可适配的微信 4.1.15.56。请先打开微信后重试，或在「启动与恢复」手动选择 Weixin.exe / Weixin.dll。路径不限制盘符；其他版本暂不适配。");return cached;}}
 internal static WeixinLocation Find(IEnumerable<string> seeds){var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(string seed in seeds)try{string raw=Environment.ExpandEnvironmentVariables(seed.Trim());if(raw.StartsWith("\"")){int close=raw.IndexOf('"',1);if(close>0)raw=raw.Substring(1,close-1);}else{int comma=raw.LastIndexOf(',');if(comma>0)raw=raw.Substring(0,comma);}string full=Path.GetFullPath(raw);if(!seen.Add(full))continue;string dir=File.Exists(full)?Path.GetDirectoryName(full):full;foreach(string baseDir in new[]{dir,Directory.GetParent(dir)==null?dir:Directory.GetParent(dir).FullName}){string dll=Path.Combine(baseDir,"4.1.15.56","Weixin.dll");if(Path.GetFileName(baseDir)=="4.1.15.56")dll=Path.Combine(baseDir,"Weixin.dll");if(!File.Exists(dll)||new FileInfo(dll).Length!=Engine.Length)continue;string parent=Path.GetDirectoryName(Path.GetDirectoryName(dll));string exe=Path.Combine(parent,"Weixin.exe");if(!File.Exists(exe))continue;return new WeixinLocation{Dll=dll,Launcher=exe};}}catch{}return null;}
 public static void Choose(string file){var found=Find(new[]{file});if(found==null)throw new IOException("所选位置未发现微信 4.1.15.56 的完整安装文件。");Engine.Normalize(File.ReadAllBytes(found.Dll));Directory.CreateDirectory(Engine.Store);File.WriteAllText(Setting,found.Dll);Reset();}
}
internal sealed partial class Studio {void AddLocationControls(Panel p){var locate=WorkspaceButton(p,"重新检测微信位置",0,550,230);var pick=WorkspaceButton(p,"手动选择微信位置…",248,550,250);locate.Click+=delegate{try{WeixinLocator.Reset();status.Text="已找到："+WeixinLocator.Current().Dll;}catch(Exception e){AppLog.Error("UI",e);status.Text=e.Message;}};pick.Click+=delegate{using(var d=new OpenFileDialog{Title="选择微信启动程序或 Weixin.dll",Filter="微信文件|Weixin.exe;Weixin.dll|所有文件|*.*"})if(d.ShowDialog(this)==DialogResult.OK)try{WeixinLocator.Choose(d.FileName);status.Text="已验证并记住本机位置："+Engine.Target;}catch(Exception e){AppLog.Error("UI",e);status.Text=e.Message;}};}}
